def is_power_of_two(k):
    if k <= 0:
        return False
    return (k & (k - 1) == 0)

solutions = []
# Search m and n up to 10
max_val = 10
for m in range(1, max_val + 1):
    for n in range(1, max_val + 1):
        # Check condition 1: m^2 + n = 2^A, A >= 2
        sum1 = m**2 + n
        if is_power_of_two(sum1):
            A = sum1.bit_length() - 1 # A = log2(sum1)
            if A >= 2:
                # Check condition 2: m + n^2 = 2^B, B >= 2
                sum2 = m + n**2
                if is_power_of_two(sum2):
                    B = sum2.bit_length() - 1 # B = log2(sum2)
                    if B >= 2:
                        solutions.append((m, n, A, B))

print("Solutions found (m, n, A, B):")
for sol in solutions:
    print(sol)

import math

def is_power_of_prime(N, p):
    if N <= 0:
        return False
    if N == 1:
        return False # We require A >= 2, so p^A >= p^2 >= 4 (since p >= 2)

    count = 0
    temp = N
    while temp > 1:
        if temp % p != 0:
            return False
        temp //= p
        count += 1
    return count >= 2

def search_solutions():
    solutions = []
    primes = [2, 3, 5, 7]
    M_MAX = 20
    N_MAX = 20

    for p in primes:
        for m in range(1, M_MAX + 1):
            for n in range(1, N_MAX + 1):
                # Condition 1: m^2 + n = p^A, A >= 2
                val1 = m**2 + n
                if not is_power_of_prime(val1, p):
                    continue

                # Condition 2: m + n^2 = p^B, B >= 2
                val2 = m + n**2
                if not is_power_of_prime(val2, p):
                    continue

                # If both conditions met, record the triple
                solutions.append((m, n, p))

    return solutions

all_solutions = search_solutions()

# Filter out the known solutions from round 1 to find 'new' ones
known_solutions = [(2, 5, 3), (5, 2, 3)]
new_solutions = [sol for sol in all_solutions if sol not in known_solutions]

print(f"Total solutions found in 1<=m,n<=20, p in {{2,3,5,7}}: {len(all_solutions)}")
print("All solutions found:")
for sol in all_solutions:
    print(sol)
print("\nNew solutions found (excluding known ones):")
if new_solutions:
